package net.mokatech.testable.api;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * Marks an interface generated by the Testable annotation processor.
 * The agent only makes a class implement an interface whose marker designates that very class.
 */
@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.TYPE)
public @interface TestableInterface {

    /** Binary name of the testable class (e.g. {@code com.example.Outer$Inner}). */
    String value();
}
